import '@/cs/extensions/CSLang'
import DOMPurify from 'dompurify'
import Vue from 'vue'

export class CSVue extends Vue {

  mounted() {
    // console.log(`mounted ${this.constructor}`)
  }

  updated() {
    // console.log(`updated ${this.constructor}`)
  }

  destroyed() {
    // console.log(`destroyed ${this.constructor}`)
  }

  // beforeRouteUpdate(to: Route, from: Route, next: any) {
  //   next()
  // }

  safeHtml(value: unknown): string {
    const sanitized = DOMPurify.sanitize(String(value == null ? '' : value), {
      ADD_ATTR: ['target', 'rel']
    })
    const template = document.createElement('template')
    template.innerHTML = sanitized
    template.content.querySelectorAll('a[target="_blank"]').forEach(link => {
      link.setAttribute('rel', 'noopener noreferrer')
    })
    return template.innerHTML
  }

  get mdAndUp() {
    return this.$vuetify.breakpoint.mdAndUp
  }

  get lgAndDown() {
    return this.$vuetify.breakpoint.lgAndDown
  }

  get mdAndDown() {
    return this.$vuetify.breakpoint.mdAndDown
  }

  get sm() {
    return this.$vuetify.breakpoint.sm
  }

  get smAndDown() {
    return this.$vuetify.breakpoint.smAndDown
  }

  get xs() {
    return this.$vuetify.breakpoint.xs
  }

  get xlAndDown() {
    return this.$vuetify.breakpoint.xlOnly
  }

  get lgAndUp() {
    return this.$vuetify.breakpoint.lgAndUp
  }
}
