import type {
  CVEarlierExperienceCopy,
  CVExperienceCopy,
  CVFlagshipCopy,
  CVLocalizedContent,
  CVSkillGroup
} from '@/model/Data/CVData'
import type {
  CVContactLabelId,
  CVEarlierExperienceId,
  CVFlagshipId,
  CVImpactId,
  CVSkillGroupId,
  SelectedResumeExperienceId
} from '@/model/Data/CVData'
import type {ExperienceId} from '@/model/Data/ContentRoutes'
import type {ProjectsData} from '@/model/Data/ProjectsData'
import type {EducationEntry, ProfileData} from '@/model/Data/ProfileData'
import type {SolutionsData} from '@/model/Data/SolutionsData'
import type {ExperienceContent} from '@/model/content/Schema'
import type {TranslationResolver} from '@/model/content/translation/TranslationResolver'
import type {TechnologyProfileContent, TechnologyCategory, TechnologyLevel} from '@/model/Data/TechnologyProfileData'

function translateArray(
  id: string,
  values: string[],
  context: string,
  resolver: TranslationResolver
): string[] {
  return values.map((value, index) => resolver.translate(`${id}.${index}`, value, `${context}, item ${index + 1}`))
}

export function translateProjects(data: ProjectsData, resolver: TranslationResolver) {
  data.forEach(project => {
    const id = `projects.${project.route}`
    project.title = resolver.translate(`${id}.title`, project.title, `Project ${project.route}: title`)
    project.subtitle = resolver.translate(`${id}.subtitle`, project.subtitle, `Project ${project.route}: subtitle`)
    project.cardSummary = resolver.translate(`${id}.cardSummary`, project.cardSummary, `Project ${project.route}: listing card summary`)
    project.client = resolver.translate(`${id}.client`, project.client, `Project ${project.route}: client display text`)
    project.role = resolver.translate(`${id}.role`, project.role, `Project ${project.route}: role`)
    project.paragraphs = translateArray(`${id}.paragraphs`, project.paragraphs, `Project ${project.route}: narrative paragraph`, resolver)
    project.problem = resolver.translate(`${id}.problem`, project.problem, `Project ${project.route}: problem statement`)
    project.contribution = resolver.translate(`${id}.contribution`, project.contribution, `Project ${project.route}: contribution`)
    project.technicalWork = translateArray(`${id}.technicalWork`, project.technicalWork, `Project ${project.route}: technical work`, resolver)
    project.outcome = resolver.translate(`${id}.outcome`, project.outcome, `Project ${project.route}: outcome`)
    project.highlights = translateArray(`${id}.highlights`, project.highlights, `Project ${project.route}: highlight`, resolver)
    project.imageAlts = translateArray(`${id}.imageAlts`, project.imageAlts, `Project ${project.route}: image accessibility text`, resolver)
    project.links.forEach((link, index) => {
      if (link.title) {
        link.title = resolver.translate(`${id}.links.${index}.title`, link.title, `Project ${project.route}: visible link title`)
      }
      link.tip = resolver.translate(`${id}.links.${index}.tip`, link.tip, `Project ${project.route}: link label`)
    })
  })
  return data
}

export function translateProfile(data: ProfileData, resolver: TranslationResolver) {
  data.title = resolver.translate('profile.title', data.title, 'Professional title beside the person name')
  data.profileImageAlts = translateArray('profile.profileImageAlts', data.profileImageAlts, 'Profile photo accessibility text', resolver)
  data.homeHeadline = resolver.translate('profile.homeHeadline', data.homeHeadline, 'Introduction page headline')
  data.homeSummary = resolver.translate('profile.homeSummary', data.homeSummary, 'Introduction page summary')
  data.locationSummary = resolver.translate('profile.locationSummary', data.locationSummary, 'Location and remote-work summary')
  data.contactIntro = resolver.translate('profile.contactIntro', data.contactIntro, 'Contact page introduction')
  data.directContactTitle = resolver.translate('profile.directContactTitle', data.directContactTitle, 'Direct contact section title')
  data.profilesTitle = resolver.translate('profile.profilesTitle', data.profilesTitle, 'Social profiles section title')
  data.socialProfilesTitle = resolver.translate('profile.socialProfilesTitle', data.socialProfilesTitle, 'General social profiles section title')

  const experienceContent = {} as Record<ExperienceId, ExperienceContent>
  for (const [experienceId, source] of Object.entries(data.translatableExperienceContent) as Array<[ExperienceId, ExperienceContent]>) {
    const id = `profile.experience.${experienceId}`
    experienceContent[experienceId] = {
      client: resolver.translate(`${id}.client`, source.client, `Experience ${experienceId}: client`),
      position: resolver.translate(`${id}.position`, source.position, `Experience ${experienceId}: position`),
      title: resolver.translate(`${id}.title`, source.title, `Experience ${experienceId}: engagement title`),
      summary: source.summary
        ? resolver.translate(`${id}.summary`, source.summary, `Experience ${experienceId}: summary`)
        : undefined,
      highlights: source.highlights.map((highlight, index) => ({
        text: resolver.translate(`${id}.highlights.${index}.text`, highlight.text, `Experience ${experienceId}: highlight`),
        link: highlight.link ? {
          ...highlight.link,
          label: resolver.translate(`${id}.highlights.${index}.link`, highlight.link.label, `Experience ${experienceId}: highlight link label`)
        } : undefined
      })),
      technologies: translateArray(`${id}.technologies`, source.technologies, `Experience ${experienceId}: technology or skill`, resolver)
    }
  }
  data.setLocalizedExperience(experienceContent)

  const educationEntries: EducationEntry[] = data.translatableEducationEntries.map((source, index) => ({
    ...source,
    school: resolver.translate(`profile.education.${index}.school`, source.school, 'Education institution name'),
    degree: resolver.translate(`profile.education.${index}.degree`, source.degree, 'Education degree')
  }))
  data.setLocalizedEducation(educationEntries)
  return data
}

export function translateSolutions(data: SolutionsData, resolver: TranslationResolver) {
  data.title = resolver.translate('solutions.title', data.title, 'Solutions page title')
  data.summary = resolver.translate('solutions.summary', data.summary, 'Solutions page summary')
  data.contactPrompt = resolver.translate('solutions.contactPrompt', data.contactPrompt, 'Solutions page contact prompt')
  data.forEach(solution => {
    const id = `solutions.${solution.route}`
    solution.title = resolver.translate(`${id}.title`, solution.title, `Solution ${solution.route}: title`)
    solution.shortTitle = resolver.translate(`${id}.shortTitle`, solution.shortTitle, `Solution ${solution.route}: short title`)
    solution.summary = resolver.translate(`${id}.summary`, solution.summary, `Solution ${solution.route}: summary`)
    solution.capabilities = translateArray(`${id}.capabilities`, solution.capabilities, `Solution ${solution.route}: capability`, resolver)
  })
  return data
}

export function translateCVContent(source: CVLocalizedContent, resolver: TranslationResolver): CVLocalizedContent {
  const text = (key: keyof Pick<CVLocalizedContent,
    | 'location' | 'specialisms' | 'summary' | 'summaryTitle' | 'impactTitle' | 'skillsTitle'
    | 'experienceTitle' | 'flagshipTitle' | 'earlierExperienceTitle' | 'educationTitle'
    | 'downloadPdfTitle' | 'openPrintableTitle' | 'completeExperienceTitle'
    | 'completeExperiencePrompt' | 'printButtonTitle' | 'cvPageButtonTitle'
    | 'projectLinkTitle'>) =>
    resolver.translate(`cv.${key}`, source[key], `CV: ${key}`)

  const contactLabels = {} as Record<CVContactLabelId, string>
  for (const [id, value] of Object.entries(source.contactLabels) as Array<[CVContactLabelId, string]>) {
    contactLabels[id] = resolver.translate(`cv.contactLabels.${id}`, value, `CV contact label: ${id}`)
  }

  const impactHighlights = {} as Record<CVImpactId, string>
  for (const [id, value] of Object.entries(source.impactHighlights) as Array<[CVImpactId, string]>) {
    impactHighlights[id] = resolver.translate(`cv.impactHighlights.${id}`, value, `CV impact highlight: ${id}`)
  }

  const skillGroups = {} as Record<CVSkillGroupId, Omit<CVSkillGroup, 'id'>>
  for (const [id, value] of Object.entries(source.skillGroups) as Array<[CVSkillGroupId, Omit<CVSkillGroup, 'id'>]>) {
    skillGroups[id] = {
      title: resolver.translate(`cv.skillGroups.${id}.title`, value.title, `CV skill group ${id}: title`),
      skills: translateArray(`cv.skillGroups.${id}.skills`, value.skills, `CV skill group ${id}: skill`, resolver)
    }
  }

  const experience = {} as Record<SelectedResumeExperienceId, CVExperienceCopy>
  for (const [id, value] of Object.entries(source.experience) as Array<[SelectedResumeExperienceId, CVExperienceCopy]>) {
    experience[id] = {
      ...value,
      title: resolver.translate(`cv.experience.${id}.title`, value.title, `CV experience ${id}: title`),
      bullets: translateArray(`cv.experience.${id}.bullets`, value.bullets, `CV experience ${id}: bullet`, resolver),
      technologies: translateArray(`cv.experience.${id}.technologies`, value.technologies, `CV experience ${id}: technology or skill`, resolver)
    }
  }

  const flagshipProjects = {} as Record<CVFlagshipId, CVFlagshipCopy>
  for (const [id, value] of Object.entries(source.flagshipProjects) as Array<[CVFlagshipId, CVFlagshipCopy]>) {
    flagshipProjects[id] = {
      ...value,
      title: resolver.translate(`cv.flagshipProjects.${id}.title`, value.title, `CV flagship project ${id}: title`),
      role: resolver.translate(`cv.flagshipProjects.${id}.role`, value.role, `CV flagship project ${id}: role`),
      bullets: translateArray(`cv.flagshipProjects.${id}.bullets`, value.bullets, `CV flagship project ${id}: bullet`, resolver),
      technologies: translateArray(`cv.flagshipProjects.${id}.technologies`, value.technologies, `CV flagship project ${id}: technology`, resolver),
      websiteLabel: resolver.translate(`cv.flagshipProjects.${id}.websiteLabel`, value.websiteLabel, `CV flagship project ${id}: website label`)
    }
  }

  const earlierExperience = {} as Record<CVEarlierExperienceId, CVEarlierExperienceCopy>
  for (const [id, value] of Object.entries(source.earlierExperience) as Array<[CVEarlierExperienceId, CVEarlierExperienceCopy]>) {
    earlierExperience[id] = {
      title: resolver.translate(`cv.earlierExperience.${id}.title`, value.title, `CV earlier experience ${id}: title`),
      summary: resolver.translate(`cv.earlierExperience.${id}.summary`, value.summary, `CV earlier experience ${id}: summary`)
    }
  }

  return {
    location: text('location'),
    specialisms: text('specialisms'),
    summary: text('summary'),
    summaryTitle: text('summaryTitle'),
    impactTitle: text('impactTitle'),
    skillsTitle: text('skillsTitle'),
    experienceTitle: text('experienceTitle'),
    flagshipTitle: text('flagshipTitle'),
    earlierExperienceTitle: text('earlierExperienceTitle'),
    educationTitle: text('educationTitle'),
    downloadPdfTitle: text('downloadPdfTitle'),
    openPrintableTitle: text('openPrintableTitle'),
    completeExperienceTitle: text('completeExperienceTitle'),
    completeExperiencePrompt: text('completeExperiencePrompt'),
    printButtonTitle: text('printButtonTitle'),
    cvPageButtonTitle: text('cvPageButtonTitle'),
    projectLinkTitle: text('projectLinkTitle'),
    contactLabels,
    impactHighlights,
    skillGroups,
    experience,
    flagshipProjects,
    earlierExperience
  }
}

export function translateTechnologyProfileContent(
  source: TechnologyProfileContent, resolver: TranslationResolver
): TechnologyProfileContent {
  const text = (key: keyof Omit<TechnologyProfileContent, 'categories' | 'levels' | 'descriptions'>) =>
    resolver.translate(`technologyProfile.${key}`, source[key], `Technology profile: ${key}`)
  const categories = {} as Record<TechnologyCategory, string>
  for (const id of Object.keys(source.categories) as TechnologyCategory[]) {
    categories[id] = resolver.translate(`technologyProfile.categories.${id}`, source.categories[id], `Technology category: ${id}`)
  }
  const levels = {} as TechnologyProfileContent['levels']
  for (const id of Object.keys(source.levels) as TechnologyLevel[]) {
    levels[id] = {
      label: resolver.translate(`technologyProfile.levels.${id}.label`, source.levels[id].label, `Self-assessed proficiency: ${id}`),
      description: resolver.translate(`technologyProfile.levels.${id}.description`, source.levels[id].description, `Proficiency definition: ${id}`)
    }
  }
  const descriptions = Object.fromEntries(Object.entries(source.descriptions).map(([id, value]) => [
    id, resolver.translate(`technologyProfile.entries.${id}.description`, value, `Practical technology experience: ${id}; preserve technology/product names`)
  ]))
  return {
    title: text('title'), downloadTitle: text('downloadTitle'), introduction: text('introduction'),
    assessmentNote: text('assessmentNote'), updatedLabel: text('updatedLabel'),
    technologyLabel: text('technologyLabel'), levelLabel: text('levelLabel'),
    yearsLabel: text('yearsLabel'), descriptionLabel: text('descriptionLabel'), legendTitle: text('legendTitle'),
    categories, levels, descriptions
  }
}
