function musicAppProject(definition: MusicAppDefinition): ProjectCatalogEntry {
  const featureImage = musicAppsImage(`feature-${definition.imageName}`)
  return {
    route: definition.route,
    clients: [{id: 'renetik', url: 'https://renetik.com/app/'}],
    periods: [{startDate: {year: 2021, month: 3}, isCurrent: true}],
    platforms: ['android'],
    technologies: musicAppTechnologies,
    images: [
      featureImage,
      ...(definition.storeImageName
        ? [musicAppsImage(`play-store-${definition.storeImageName}`)]
        : []),
      ...definition.galleryImages
    ],
    links: [
      ...(definition.websitePath ? [{
        icon: 'fa-globe',
        kind: 'website' as const,
        title: `${definition.title} website`,
        url: `https://renetik.com/app/${definition.websitePath}`
      }] : []),
      {
        icon: 'fab fa-google-play',
        kind: 'app',
        title: definition.title,
        image: featureImage,
        url: `https://play.google.com/store/apps/details?id=${definition.packageName}`
      },
      ...(definition.hasFullVersion ? [{
        icon: 'fab fa-google-play',
        kind: 'app' as const,
        title: `${definition.title} Full`,
        image: featureImage,
        url: `https://play.google.com/store/apps/details?id=${definition.packageName}.full_2_9`
      }] : [])
    ],
    youtube: []
  }
}

