import {generatedLocaleEntryModules, generatedLocaleMetadata} from '@/model/content/generated-locales/catalogs'
import type {GeneratedLocale} from '@/model/content/generated-locales/catalogs'
import type {
  GeneratedLocaleMetadata,
  RuntimeTranslationCatalog,
  TranslationEntries
} from '@/model/content/translation/TranslationCatalog'

export type {GeneratedLocale} from '@/model/content/generated-locales/catalogs'

const metadata = generatedLocaleMetadata as Readonly<Record<string, GeneratedLocaleMetadata>>
const catalogs: Record<string, RuntimeTranslationCatalog> = {}

export const generatedLocaleCodes = Object.keys(metadata) as GeneratedLocale[]

export const generatedLocaleOptions = generatedLocaleCodes.map(code => ({
  code,
  name: metadata[code].languageName,
  shortName: metadata[code].shortName
}))

/** Language and Open Graph facts, available without loading the locale's translations. */
export function generatedLocaleMetadataFor(locale: string): GeneratedLocaleMetadata | undefined {
  return metadata[locale]
}

/** Translations of an already loaded locale. */
export function generatedLocaleCatalog(locale: string): RuntimeTranslationCatalog | undefined {
  return catalogs[locale]
}

export function registerGeneratedLocaleEntries(locale: string, entries: TranslationEntries) {
  const localeMetadata = metadata[locale]
  if (!localeMetadata) throw new Error(`Unknown generated locale: ${locale}`)
  catalogs[locale] = {...localeMetadata, entries}
  return catalogs[locale]
}

// Webpack resolves a JSON chunk to a module namespace, Node to the parsed object.
function moduleEntries(entryModule: unknown): TranslationEntries {
  const namespace = entryModule as {default?: TranslationEntries}
  return namespace.default || entryModule as TranslationEntries
}

/**
 * Load one locale's translations from its own chunk. Only the locale the page
 * renders in is ever downloaded; unknown locales resolve to undefined so the
 * caller falls back to the English source content.
 */
export async function loadGeneratedLocaleCatalog(locale: string): Promise<RuntimeTranslationCatalog | undefined> {
  const loaded = catalogs[locale]
  if (loaded) return loaded
  const entryModule = generatedLocaleEntryModules[locale]
  if (!entryModule) return undefined
  return registerGeneratedLocaleEntries(locale, moduleEntries(await entryModule()))
}
