import {defaultLocale, locales} from '@/model/content/Schema'
import type {Locale as LocaleCode} from '@/model/content/Schema'
import {generatedLocaleOptions} from '@/model/content/translation/GeneratedLocaleCatalogs'

const localePreferenceKey = 'locale'

export const localeOptions: ReadonlyArray<{code: LocaleCode; name: string; shortName: string}> = [
  {code: 'en', name: 'English', shortName: 'EN'},
  ...generatedLocaleOptions
]

function ensureLeadingSlash(path: string): string {
  if (!path) return '/'
  return path.startsWith('/') ? path : `/${path}`
}

function pathLocale(pathname: string): LocaleCode | null {
  const firstSegment = ensureLeadingSlash(pathname).split('/')[1]
  return locales.find(locale => locale !== defaultLocale && locale === firstSegment) || null
}

/** Locale selected by a pathname. English uses unprefixed routes. */
export function parseLocale(pathname: string): LocaleCode {
  return pathLocale(pathname) || defaultLocale
}

/** Strip any locale prefix, returning the locale-neutral path (always leading-slash). */
export function neutralPath(pathname: string): string {
  const path = ensureLeadingSlash(pathname)
  const locale = pathLocale(path)
  if (!locale) return path
  const rest = path.slice(locale.length + 1)
  return rest === '' ? '/' : ensureLeadingSlash(rest)
}

/** Build a locale-prefixed path for `locale` from a locale-neutral path. */
export function localizePath(locale: LocaleCode, neutral: string): string {
  const path = ensureLeadingSlash(neutral)
  if (locale === defaultLocale) return path
  const prefix = `/${locale}`
  return path === '/' ? `${prefix}/` : `${prefix}${path}`
}

/** Normalize bare locale roots such as `/es` to their canonical directory route. */
export function normalizeBareLocale(pathname: string): string {
  const locale = pathLocale(pathname)
  return locale && pathname === `/${locale}` ? `/${locale}/` : pathname
}

/** vue-router `base` for a locale. */
export function routerBase(locale: LocaleCode): string {
  return locale === defaultLocale ? '/' : `/${locale}/`
}

export function preferredLocale(languages: readonly string[], storedLocale?: string | null): LocaleCode {
  if (storedLocale && locales.includes(storedLocale as LocaleCode)) return storedLocale as LocaleCode
  for (const language of languages) {
    const code = language.toLowerCase().split('-')[0] as LocaleCode
    if (locales.includes(code)) return code
  }
  return defaultLocale
}

export function rememberLocale(locale: LocaleCode) {
  try {
    window.localStorage.setItem(localePreferenceKey, locale)
  } catch (_) {
    // Language selection still works when storage is blocked.
  }
}

/** Redirect an unprefixed first visit to a saved or browser-preferred locale. */
export function preferredLocaleRedirect(): string | null {
  if (typeof window === 'undefined' || pathLocale(window.location.pathname)) return null
  let storedLocale: string | null = null
  try {
    storedLocale = window.localStorage.getItem(localePreferenceKey)
  } catch (_) {
    // Fall back to browser languages when storage is blocked.
  }
  const locale = preferredLocale(window.navigator.languages || [window.navigator.language], storedLocale)
  if (locale === defaultLocale) return null
  const path = localizePath(locale, window.location.pathname)
  return `${path}${window.location.search}${window.location.hash}`
}

function activeLocale(): LocaleCode {
  if (typeof window === 'undefined' || !window.location) return defaultLocale
  return parseLocale(window.location.pathname)
}

export const Locale = {
  /** Locale for the current page, derived from the URL. Fixed for the page lifetime. */
  get active(): LocaleCode {
    return activeLocale()
  },

  /** Prefix a locale-neutral, non-router path for the current page locale. */
  activePathFor(path: string): string {
    return localizePath(activeLocale(), neutralPath(path))
  },

  /** Build a path for a specified target locale (used by the language picker). */
  pathFor(locale: LocaleCode, path: string): string {
    return localizePath(locale, neutralPath(path))
  }
}
